from skynet_validation.evidence import need,ident,canonical,commitment
DOMAINS=tuple('PLAN-%03d'%i for i in range(1,7))
def validate(t):
 need(type(t)is dict and set(t)=={'id','domain','track','seed','difficulty','input'},'TASK');ident(t['id']);need(t['domain']in DOMAINS,'DOMAIN');need(t['track']==('native_planning' if t['domain']=='PLAN-002' else 'infrastructure'),'TRACK');need(type(t['seed'])is int and t['seed']in(1001,2003),'SEED');need(t['difficulty']in('basic','intermediate','advanced'),'DIFFICULTY');x=t['input'];need(type(x)is dict and set(x)=={'goal_id','count','kind','priorities','value'},'INPUT');ident(x['goal_id']);need(type(x['count'])is int and 2<=x['count']<=4,'COUNT');need(x['kind']in('represent','decompose','cycle','missing','valid','capacity','unavailable','success','failure','worker_failure','requeue','release'),'KIND');allowed={'PLAN-001':('represent',),'PLAN-002':('decompose',),'PLAN-003':('cycle','missing','valid'),'PLAN-004':('capacity','unavailable'),'PLAN-005':('success','failure'),'PLAN-006':('worker_failure','requeue','release')};need(x['kind']in allowed[t['domain']],'DOMAIN_KIND');need(type(x['priorities'])is list and len(x['priorities'])==x['count'] and all(type(v)is int and 0<=v<=9 for v in x['priorities']),'PRIORITIES');need(type(x['value'])is int and 0<=x['value']<=100000,'VALUE');canonical(t);return t

